import re
import unicodedata


def slugify(value):
    decomposed = unicodedata.normalize("NFKD", value)
    without_marks = "".join(
        ch for ch in decomposed if not unicodedata.combining(ch)
    )
    return re.sub(r"[^a-z0-9]+", "-", without_marks.lower()).strip("-")
